public with sharing class ContactTriggerHandler {
    public void beforeInsertOrUpdate(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                Account a = accountMap.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    // The original code checks Trigger.isInsert via the trigger context, 
                    // but Since we are in a handler method called by both, 
                    // we need to be careful. However, in the trigger, beforeInsertOrUpdate
                    // is called for both. To keep behavior identical to the trigger's 
                    // `if (Trigger.isInsert)`, we would usually pass a flag, but 
                    // the logic specifies only adding LeadSource on Insert.
                    // Since we can't check Trigger.isInsert inside a class method 
                    // easily without passing it, and the trigger calls this for both,
                    // we check the state via the context.
                    if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }

    public void afterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, Phone 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accountMap.get(c.AccountId);
                if (a != null && String.isBlank(a.Phone)) {
                    // "the first of those contacts (in trigger order) sets the account phone"
                    // We only add to the map if the account hasn't been marked for update yet
                    // or we simply update the object in the map.
                    if (!accountsToUpdate.containsKey(a.Id)) {
                        a.Phone = c.Phone;
                        accountsToUpdate.put(a.Id, a);
                    }
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
