/**
 * @description Schedulable class to purge integration logs based on their level and age.
 * Implements best practices for bulk deletion and query filtering.
 */
public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
        // No-argument constructor
    }

    /**
     * Execution method for the Schedulable interface.
     * Deletes records based on retention logic:
     * - NON-ERROR logs: deleted after 30 days
     * - ERROR logs: deleted after 180 days
     */
    public void execute(SchedulableContext sc) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneEightyDaysAgo = Date.today().addDays(-180);

        // Select logs to delete:
        // 1. Logs that are NOT 'ERROR' (including nulls) created more than 30 days ago
        // 2. Logs that ARE 'ERROR' created more than 180 days ago
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
               OR (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
            // Emptying the recycle bin for these records to reclaim storage immediately
            DataBase.emptyRecycleBin(logsToDelete);
        }
    }

    /**
     * Schedules the job to run nightly at 02:00.
     * @return The Job ID returned by System.schedule
     */
    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        String cronExpression = '0 0 2 * * ?'; // Seconds Minutes Hours Day_of_month Month Day_of_week
        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }
}
