public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> records) {
        super(Opportunity.class, records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void onBeforeInsert() {
        validateAmountNotNegative();
    }

    public override void onBeforeUpdate() {
        validateAmountNotNegative();
        validateAmountLockedOnWon();
    }

    private void validateAmountNotNegative() {
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    private void validateAmountLockedOnWon() {
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            // Check if the record was already Closed Won before this transaction
            // using the getOldMap() functionality provided by fflib (via the records list mapping)
            Opportunity oldOpp = (Opportunity) getOldMap().get(opp.Id);

            if (oldOpp != null && oldOpp.StageName == 'Closed Won') {
                if (opp.Amount != oldOpp.Amount) {
                    error('Amount cannot change on a won opportunity.', opp, 'Amount');
                }
            }
        }
    }
}
