public with sharing class ContactPhoneCleanup {
    /**
     * Normalizes phone numbers for a list of Contact IDs.
     * Removes any character that is not a digit or a leading plus sign.
     * 
     * @param contactIds List of Contact IDs to process
     * @return Map of Contact ID to the first error message for records that failed to save.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new Map<Id, String>();
        }

        // Fetch contacts that have a phone number
        List<Contact> contactsToProcess = [
            SELECT Id, Phone 
            FROM Contact 
            WHERE Id IN :contactIds AND Phone != null
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : contactsToProcess) {
            // Replace all characters that are NOT (^) a digit (0-9) or a plus sign (+)
            String normalizedPhone = con.Phone.replaceAll('[^0-9+]', '');

            // Only queue for update if the value actually changed
            if (normalizedPhone != con.Phone) {
                con.Phone = normalizedPhone;
                contactsToUpdate.add(con);
            }
        }

        Map<Id, String> errorMap = new Map<Id, String>();

