public with sharing class AccountCountrySync {
    /**
     * Syncs BillingCountry from Account to related Contacts based on specific criteria.
     * 
     * @param newAccounts The list of updated accounts (Trigger.new)
     * @param oldMap The map of account versions prior to update (Trigger.oldMap)
     */
    public static void syncCountry(List<Account> newAccounts, Map<Id, Account> oldMap) {
        Set<Id> accountsToProcess = new Set<Id>();
        Map<Id, String> accountNewCountryMap = new Map<Id, String>();
        Map<Id, String> accountOldCountryMap = new Map<Id, String>();

        // Filter for accounts where BillingCountry actually changed
        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                accountsToProcess.add(acc.Id);
                accountNewCountryMap.put(acc.Id, acc.BillingCountry);
                accountOldCountryMap.put(acc.Id, oldAcc.BillingCountry);
            }
        }

        if (accountsToProcess.isEmpty()) {
            return;
        }

        // Bulk-safe query: Only fetch contacts for the affected accounts.
        // Fetching all 2.3 million contacts would result in a LimitException.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [SELECT Id, AccountId, MailingCountry 
                           FROM Contact 
                           WHERE AccountId IN :accountsToProcess]) {

            String newCountry = accountNewCountryMap.get(con.AccountId);
            String oldCountry = accountOldCountryMap.get(con.AccountId);

            // Criteria: MailingCountry is blank OR equal to the account's previous BillingCountry
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
