import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api value;
    @api options = [];

    @track _internalValue;
    activeOptionId = '';

    // We use a getter for processed options to handle IDs and selection states
    // without mutating the input array.
    get processedOptions() {
        if (!this.options) return [];
        return this.options.map((opt, index) => ({
            ...opt,
            id: `option-${index}`,
            isSelected: opt.value === this.value
        }));
    }

    // The active option must be the selected one, or the first one.
    // This is called whenever the component renders or the value changes.
    connectedCallback() {
        this.updateActiveOption();
    }

    // Handle external value changes from the parent
    // Since we can't use a setter and getter on the same property for @api,
    // we react to the value change via the renderedCallback or simple property logic.
    // However, the prompt says "parent can change it at any time", implying a public property.
    // In LWC, @api properties are reactive.

    renderedCallback() {
        this.updateActiveOption();
    }

    updateActiveOption() {
        const opts = this.processedOptions;
        if (opts.length === 0) return;

        const selectedOption = opts.find(opt => opt.value === this.value);
        if (selectedOption) {
            this.activeOptionId = selectedOption.id;
        } else {
            this.activeOptionId = opts[0].id;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const val = li.dataset.value;
        const id = li.id;

        this.setActiveAndSelect(id, val);
    }

    handleKeyDown(event) {
        const opts = this.processedOptions;
        if (opts.length === 0) return;

        const currentIndex = opts.findIndex(opt => opt.id === this.activeOptionId);
        let nextIndex = currentIndex;
        let handled = false;

        switch (event.key) {
            case 'ArrowDown':
                if (currentIndex < opts.length - 1) {
                    nextIndex = currentIndex + 1;
                    handled = true;
                }
                break;
            case 'ArrowUp':
                if (currentIndex > 0) {
                    nextIndex = currentIndex - 1;
                    handled = true;
                }
                break;
            case 'Home':
                nextIndex = 0;
                handled = true;
                break;
            case 'End':
                nextIndex = opts.length - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this.selectActive();
                handled = true;
                break;
        }

        if (handled) {
            event.preventDefault();
            if (event.key !== 'Enter' && event.key !== ' ') {
                this.activeOptionId = opts[nextIndex].id;
            }
        }
    }

    selectActive() {
        const opts = this.processedOptions;
        const activeOption = opts.find(opt => opt.id === this.activeOptionId);
        if (activeOption) {
            this.setActiveAndSelect(activeOption.id, activeOption.value);
        }
    }

    setActiveAndSelect(id, value) {
        this.activeOptionId = id;

        if (this.value !== value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: value }
            }));
        }
    }
}
