public with sharing class FamilyService {
    /**
     * Links parents to children in NPSP.
     * For each pair, creates a relationship where the parent is the 'Parent' of the child.
     * NPSP Relationship Lookup settings handle the reciprocal record creation and labeling.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allContactIds.add(childId);
            allContactIds.add(parentIdByChildId.get(childId));
        }

        // NPSP Relationship object name is npsp__Relationship__c
        // We query existing relationships between the provided contacts to ensure idempotency.
        // We check both directions because NPSP creates reciprocal records.
        Set<String> existingPairs = new Set<String>();
        for (npsp__Relationship__c rel : [
            SELECT npsp__Contact__c, npsp__Related_Contact__c 
            FROM npsp__Relationship__c 
            WHERE (npsp__Contact__c IN :allContactIds AND npsp__Related_Contact__c IN :allContactIds)
        ]) {
            // Create a unique key for the pair regardless of direction
            Id id1 = rel.npsp__Contact__c;
            Id id2 = rel.npsp__Related_Contact__c;
            existingPairs.add(id1 < id2 ? id1 + '-' + id2 : id2 + '-' + id1);
        }

        List<npsp__Relationship__c> relationshipsToCreate = new List<npsp__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;

            // Check if a relationship already exists between these two contacts
            String pairKey = childId < parentId ? childId + '-' + parentId : parentId + '-' + childId;
            if (!existingPairs.contains(pairKey)) {
                // To make the Parent the 'Parent' of the Child:
                // npsp__Contact__c = The Person (Child)
                // npsp__Related_Contact__c = The Relative (Parent)
                relationshipsToCreate.add(new npsp__Relationship__c(
                    npsp__Contact__c = childId,
                    npsp__Related_Contact__c = parentId,
                    npsp__Status__c = 'Current',
                    npsp__Type__c = 'Parent'
                ));

                // Mark as existing to prevent duplicate processing if the map contains reverse entries
                existingPairs.add(pairKey);
            }
        }

        if (!relationshipsToCreate.isEmpty()) {
            insert relationshipsToCreate;
        }
    }
}
